def top_k_counts(words: list[str], k: int) -> list[tuple[str, int]]:
    if k <= 0:
        return []
    info: dict[str, list[int, int, str]] = {}
    for i, w in enumerate(words):
        low = w.lower()
        if low not in info:
            info[low] = [1, i, w]          # count, first_index, first_spelling
        else:
            info[low][0] += 1
    items = [(low, cnt, idx, spell) for low, (cnt, idx, spell) in info.items()]
    items.sort(key=lambda x: (-x[1], x[2]))
    return [(spell, cnt) for _, cnt, _, spell in items[:k]]

import json
import math

def parse_jsonl_metrics(lines: list[str]) -> dict:
    invalid = 0
    service_data = {}  # service -> {"latencies": [], "ok": 0}
    for line in lines:
        line = line.strip()
        if not line:
            continue
        try:
            record = json.loads(line)
        except json.JSONDecodeError:
            invalid += 1
            continue
        service = record.get("service")
        latency = record.get("latency_ms")
        status = record.get("status")
        if not isinstance(service, str):
            invalid += 1
            continue
        if not isinstance(latency, (int, float)):
            invalid += 1
            continue
        if not isinstance(status, (int, float)):
            invalid += 1
            continue
        if service not in service_data:
            service_data[service] = {"latencies": [], "ok": 0}
        data = service_data[service]
        data["latencies"].append(float(latency))
        if 200 <= status < 300:
            data["ok"] += 1
    result = {"invalid": invalid}
    for svc in sorted(service_data.keys()):
        data = service_data[svc]
        latencies = data["latencies"]
        n = len(latencies)
        ok = data["ok"]
        count = n
        ok_rate = ok / n if n > 0 else 0.0
        if n == 0:
            p95 = None
        else:
            sorted_lat = sorted(latencies)
            idx = math.ceil(0.95 * n) - 1
            p95 = sorted_lat[idx]
        result[svc] = {
            "count": count,
            "ok_rate": ok_rate,
            "p95_latency_ms": p95
        }
    return result

