import heapq
from typing import List, Tuple, Dict, Set


class CycleError(Exception):
    def __init__(self, cycle: List[str]):
        self.cycle = cycle
        super().__init__(f"Cycle detected: {cycle}")


def dependency_plan(nodes: List[str], edges: List[Tuple[str, str]]) -> List[str]:
    node_set = set(nodes)
    adj: Dict[str, Set[str]] = {n: set() for n in nodes}
    indegree: Dict[str, int] = {n: 0 for n in nodes}

    for a, b in edges:
        if a not in node_set or b not in node_set:
            raise ValueError(f"Edge ({a!r}, {b!r}) contains unknown node")
        if a == b:
            raise CycleError([a, a])
        if b not in adj[a]:
            adj[a].add(b)
            indegree[b] += 1

    # Kahn's algorithm with lexicographically smallest choice
    zero_indeg = [n for n in nodes if indegree[n] == 0]
    heapq.heapify(zero_indeg)
    result: List[str] = []

    while zero_indeg:
        u = heapq.heappop(zero_indeg)
        result.append(u)
        for v in adj[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                heapq.heappush(zero_indeg, v)

    if len(result) != len(nodes):
        # Find a cycle to report
        visited: Set[str] = set()
        onstack: Dict[str, int] = {}
        path: List[str] = []
        cycle: List[str] = []

        def dfs(u: str) -> bool:
            nonlocal cycle
            visited.add(u)
            onstack[u] = len(path)
            path.append(u)
            for v in adj[u]:
                if v not in visited:
                    if dfs(v):
                        return True
                elif v in onstack:
                    start = onstack[v]
                    cycle = path[start:] + [v]
                    return True
            path.pop()
            del onstack[u]
            return False

        for n in nodes:
            if n not in visited:
                if dfs(n):
                    break
        raise CycleError(cycle)

    return result
