class _StreamingGroupSum:
    def __init__(self, rows):
        self._rows = rows
        self.invalid_count = 0

    def __iter__(self):
        sums = {}
        order = []
        for item in self._rows:
            try:
                _, key, val = item
            except Exception:
                self.invalid_count += 1
                continue
            try:
                v = float(val)
            except Exception:
                self.invalid_count += 1
                continue
            if key not in sums:
                sums[key] = 0.0
                order.append(key)
            sums[key] += v
        for key in order:
            yield (key, sums[key])

def streaming_group_sum(rows):
    return _StreamingGroupSum(rows)
