import copy
from typing import Any, Dict, List, Tuple

def apply_patch_ops(document: Dict[str, Any], operations: List[Tuple[str, str, Any]]) -> Dict[str, Any]:
    """
    Apply a list of patch operations to a nested dictionary transactionally.
    Each operation is a tuple (op, path, value) where:
        op   : 'set' | 'delete' | 'increment'
        path : dot‑separated key path, e.g. "user.profile.age"
        value: depends on op (set: any, delete: ignored, increment: numeric)
    The function deep‑copies the input, applies all operations, and returns the new
    document only if every operation succeeds; otherwise it raises an exception
    and leaves the original document unchanged.
    """
    doc_copy = copy.deepcopy(document)

    def _get_parent_and_last(doc: Dict[str, Any], path: str, op: str):
        """Return (parent_dict, last_key) for the given path.
        For 'set' creates missing intermediate dicts as needed.
        For 'delete' and 'increment' raises KeyError if any intermediate is missing.
        """
        parts = path.split('.')
        if not parts or any(not p for p in parts):
            raise ValueError(f"Invalid path: '{path}'")
        parent = doc
        for p in parts[:-1]:
            if isinstance(parent, dict) and p in parent:
                parent = parent[p]
            else:
                if op == 'set':
                    parent[p] = {}
                    parent = parent[p]
                else:
                    raise KeyError(f"Intermediate key '{p}' not found for path '{path}'")
        return parent, parts[-1]

    try:
        for op, path, value in operations:
            if op == 'set':
                parent, last = _get_parent_and_last(doc_copy, path, op)
                parent[last] = value
            elif op == 'delete':
                try:
                    parent, last = _get_parent_and_last(doc_copy, path, op)
                except KeyError:
                    # Path does not exist – nothing to delete, ignore per spec
                    continue
                if last in parent:
                    del parent[last]
            elif op == 'increment':
                parent, last = _get_parent_and_last(doc_copy, path, op)
                if last not in parent:
                    raise KeyError(f"Key '{last}' not found for increment at path '{path}'")
                cur = parent[last]
                if not isinstance(cur, (int, float)):
                    raise TypeError(f"Value at '{path}' is not numeric for increment")
                if not isinstance(value, (int, float)):
                    raise TypeError(f"Increment value must be numeric, got {type(value).__name__}")
                parent[last] = cur + value
            else:
                raise ValueError(f"Unsupported operation '{op}'")
        return doc_copy
    except Exception:
        # Any failure aborts the transaction; the local copy is discarded.
        raise
