    # Internal helpers
    # ------------------------------------------------------------------ #
    def _now(self) -> float:
        return time.time()

    def _is_expired(self, expiry: Optional[float]) -> bool:
        return expiry is not None and self._now() >= expiry

    def _set_locked(self, key: Any, value: Any) -> None:
        """Insert or update a cache entry assuming caller holds _lock."""
        if self._maxsize > 0 and len(self._cache) >= self._maxsize:
            # Simple eviction: remove a random item (could be LRU in a real impl)
            # Here we just pop an arbitrary item to keep size bounded.
            self._cache.pop(next(iter(self._cache)))
        expiry = self._now() + self._ttl if self._ttl > 0 else None
        self._cache[key] = (value, expiry)

    def _get_locked(self, key: Any) -> Any:
        """Retrieve a value if present and not expired; caller holds _lock."""
        entry = self._cache.get(key)
        if entry is None:
            raise KeyError(key)
        value, expiry = entry
        if self._is_expired(expiry):
            del self._cache[key]
            raise KeyError(key)
        return value

    def _delete_locked(self, key: Any) -> None:
        """Remove a key if present; caller holds _lock."""
        self._cache.pop(key, None)

