import copy
import threading
from typing import Any, Dict, Optional, Tuple


class VersionedStore:
    def __init__(self) -> None:
        self._data: Dict[str, Tuple[Any, int]] = {}
        self._lock = threading.RLock()

    def read(self, key: str) -> Any:
        with self._lock:
            entry = self._data.get(key)
            if entry is None:
                return None
            value, _ = entry
            return copy.deepcopy(value)

    def compare_and_set(self, key: str, expected_version: int, value: Any) -> bool:
        with self._lock:
            entry = self._data.get(key)
            cur_version = entry[1] if entry else None
            if cur_version != expected_version:
                return False
            self._data[key] = (copy.deepcopy(value), cur_version + 1)
            return True

    def delete(self, key: str, expected_version: int) -> bool:
        with self._lock:
            entry = self._data.get(key)
            cur_version = entry[1] if entry else None
            if cur_version != expected_version:
                return False
            del self._data[key]
            return True

    def snapshot(self) -> Dict[str, Any]:
        with self._lock:
            snap: Dict[str, Any] = {}
            for k, (v, _) in self._data.items():
                snap[k] = copy.deepcopy(v)
            return snap
