# Process large TSV access log (timestamp,status,latency_ms,path)
# Output per‑path: request count, 5xx count, p99 latency (ms)
# Sorted by 5xx count descending, then path ascending.
# p99 is taken as the value at index ceil(0.99 × N) after sorting the latency list for that path.
# This requires keeping all latencies for each path in awk arrays (O(requests per path) memory),
# but streams the file so no entire file is ever held in a shell variable.

awk -F'\t' '
{
    p = $4
    req[p]++
    if ($2 >= 500 && $2 < 600) bad[p]++
    lat[p, ++cnt[p]] = $3
}
END {
    for (p in req) {
        n = cnt[p]
        if (n == 0) { p99 = 0 }
        else {
            delete tmp
            for (i = 1; i <= n; i++) tmp[i] = lat[p,i]
            asort(tmp)                     # numeric, ascending
            idx = int(0.99 * n)            # floor(0.99·n)
            if (idx < n) idx++             # make it ceil
            if (idx < 1) idx = 1
            p99 = tmp[idx]
        }
        printf "%s\t%d\t%d\t%d\n", p, req[p], bad[p]+0, p99
    }
}' "$1" |
